use crate::aap::caps::{http_client, notifier};
use crate::wasi::clocks::wall_clock;

struct Node;

const NOTIFY_ATTEMPTS: u32 = 3;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Clock: read the wall-clock time.
        let now = wall_clock::now();
        let seconds = now.seconds;

        // HTTP: one fetch. A transport failure is a value, not a trap.
        // Fetching a host outside the allowlist still traps at the boundary.
        let (fetched, fetch_note) = match http_client::fetch(&feed_url) {
            Ok(body) => {
                let n = body.chars().count();
                let n = if n > u32::MAX as usize { u32::MAX } else { n as u32 };
                (n, format!("fetched {} chars", n))
            }
            Err(err) => (0u32, format!("fetch failed: {}", err)),
        };

        // Notifier: report the heartbeat.
        let message = format!(
            "heartbeat at {}s: {} from {}",
            seconds, fetch_note, feed_url
        );

        let mut notified = false;
        for _ in 0..NOTIFY_ATTEMPTS {
            if notifier::notify(&message) {
                notified = true;
                break;
            }
        }

        // The contract requires `notified == true` on every output.
        // If the notifier never accepts the message, no valid output
        // exists, so fail instead of returning a report that breaks it.
        if !notified {
            panic!("notifier refused the heartbeat notification");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
